<template>
  <div class="page-heading"><div><div class="eyebrow">COMPANY & INDICATOR</div><h1>公司與指標</h1><p>按客戶管理公司組、香港／澳門公司與所屬兩地牌。</p></div></div>
  <section class="panel"><div class="panel-head"><div><h2>客戶</h2><p>選擇要管理的客戶檔案</p></div></div><select v-model="customerId"><option value="">請選擇客戶</option><option v-for="item in customers" :key="item.id" :value="item.id">{{ item.name }}</option></select></section>
  <template v-if="customerId">
    <section class="panel"><div class="panel-head"><div><h2>新增公司組</h2><p>一組公司可掛一個或多個指標。</p></div></div><div class="form-grid"><label>公司組名稱<input v-model="newGroup.name"/></label><label>備註<input v-model="newGroup.notes"/></label></div><button class="button primary" @click="createGroup">新增公司組</button></section>
    <section v-for="group in groups" :key="group.id" class="panel company-group-card"><div class="panel-head"><div><span class="section-kicker">COMPANY GROUP</span><h2>{{ group.name }}</h2><p>{{ group.notes || '尚未填寫公司組備註' }}</p></div><button class="button" @click="editGroup(group)">編輯公司組</button></div>
      <div v-if="group.warnings?.length" class="status-warnings"><span v-for="warning in group.warnings" :key="warning" class="warning">{{ warning }}</span></div>
      <div class="company-columns"><div><h3>香港／澳門公司</h3><div v-for="company in foreignCompanies(group)" :key="company.id" class="company-card" :class="companyCardClass(company)"><div class="company-card-title"><strong>{{ company.jurisdiction }} · {{ company.name }}</strong><span v-if="company.status !== '存續'" class="company-status" :class="statusClass(company.status)">{{ company.status }}</span></div><span>登記號碼：{{ company.registration_no || '—' }}</span><span>成立日期：{{ company.incorporated_on || '—' }}</span><span>納稅人類型：{{ company.taxpayer_type || '—' }}</span><div class="company-card-actions"><button class="button" @click="editCompany(company)">編輯</button><ExpiryPanel owner-type="company" :owner-id="company.id" @saved="$emit('saved',$event)" @error="$emit('error',$event)"/></div></div><div v-if="!foreignCompanies(group).length" class="empty">尚未登記香港／澳門公司</div></div><div><h3>內地公司</h3><div v-for="company in mainlandCompanies(group)" :key="company.id" class="company-card" :class="companyCardClass(company)"><div class="company-card-title"><strong>{{ company.jurisdiction }} · {{ company.name }}</strong><span v-if="company.status !== '存續'" class="company-status" :class="statusClass(company.status)">{{ company.status }}</span></div><span>登記號碼：{{ company.registration_no || '—' }}</span><span>成立日期：{{ company.incorporated_on || '—' }}</span><span>納稅人類型：{{ company.taxpayer_type || '—' }}</span><div class="company-card-actions"><button class="button" @click="editCompany(company)">編輯</button><ExpiryPanel owner-type="company" :owner-id="company.id" @saved="$emit('saved',$event)" @error="$emit('error',$event)"/></div></div><div v-if="!mainlandCompanies(group).length && !group.warnings?.length" class="empty">尚未登記內地公司</div></div></div>
      <div class="group-plates"><h3>所屬兩地牌</h3><div v-for="plate in group.plates" :key="plate.id" class="record-row"><button class="phase-link" @click="$emit('plate',plate.id)">{{ plate.mainland_plate || '內地車牌待補' }} · {{ plate.local_plate || '港澳車牌待補' }}</button><span>{{ plate.route }} · 類別：{{ plate.indicator_category || '待設定' }} · 口岸：{{ plate.port || '待設定' }}</span><span>{{ plate.usage_status }}</span></div><div v-if="!group.plates.length" class="empty">尚未掛接兩地牌</div></div>
    </section>
    <section v-if="ungrouped.length" class="panel"><div class="panel-head"><div><h2>未分組公司</h2><p>可編輯後加入現有公司組。</p></div></div><div class="company-columns"><div v-for="company in ungrouped" :key="company.id" class="company-card" :class="companyCardClass(company)"><div class="company-card-title"><strong>{{ company.jurisdiction }} · {{ company.name }}</strong><span v-if="company.status !== '存續'" class="company-status" :class="statusClass(company.status)">{{ company.status }}</span></div><span>登記號碼：{{ company.registration_no || '—' }}</span><span>成立日期：{{ company.incorporated_on || '—' }}</span><span>納稅人類型：{{ company.taxpayer_type || '—' }}</span><button class="button" @click="editCompany(company)">編輯</button><ExpiryPanel owner-type="company" :owner-id="company.id" @saved="$emit('saved',$event)" @error="$emit('error',$event)"/></div></div></section>
    <section class="panel"><div class="panel-head"><div><h2>{{ editingCompany ? '編輯公司' : '新增公司' }}</h2><p>公司資料與公司組關聯</p></div></div><div class="form-grid"><label>公司組<select v-model="form.groupId"><option value="">未分組</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.name }}</option></select></label><label>司法區<select v-model="form.jurisdiction"><option v-for="area in ['香港','澳門','內地']" :key="area">{{ area }}</option></select></label><label>公司名稱<input v-model="form.name"/></label><label>登記號碼<input v-model="form.registrationNo"/></label><label>成立日期<input v-model="form.incorporatedOn" type="date"/></label><label>納稅人類型<input v-model="form.taxpayerType"/></label><label>狀態<select v-model="form.status"><option v-for="status in statuses" :key="status">{{ status }}</option></select></label><label>狀態變更日期<input v-model="form.statusChangedOn" type="date"/></label><label>備註<input v-model="form.notes"/></label></div><button class="button primary" @click="saveCompany">儲存公司</button></section>
  </template>
  <div v-if="dialog" class="overlay" @click.self="dialog=null"><div class="dialog"><div class="dialog-head"><div><div class="eyebrow">EDIT RECORD</div><h2>{{ dialog === 'group' ? '編輯公司組' : '編輯公司' }}</h2></div><button class="close" @click="dialog=null">×</button></div><template v-if="dialog==='group'"><label>公司組名稱<input v-model="dialogForm.name"/></label><label>備註<textarea v-model="dialogForm.notes"></textarea></label><button class="button primary full" @click="saveGroup">儲存公司組</button></template><template v-else><div class="form-grid"><label>公司組<select v-model="dialogForm.groupId"><option value="">未分組</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.name }}</option></select></label><label>司法區<select v-model="dialogForm.jurisdiction"><option v-for="area in ['香港','澳門','內地']" :key="area">{{ area }}</option></select></label><label>公司名稱<input v-model="dialogForm.name"/></label><label>登記號碼<input v-model="dialogForm.registrationNo"/></label><label>成立日期<input v-model="dialogForm.incorporatedOn" type="date"/></label><label>納稅人類型<input v-model="dialogForm.taxpayerType"/></label><label>狀態<select v-model="dialogForm.status"><option v-for="status in statuses" :key="status">{{ status }}</option></select></label><label>狀態變更日期<input v-model="dialogForm.statusChangedOn" type="date"/></label><label>備註<input v-model="dialogForm.notes"/></label></div><div v-if="dialogForm.jurisdiction==='香港'" class="lookup-box"><button class="button" :disabled="lookingUp" @click="lookupCompany">{{ lookingUp ? '查詢中…' : '向公司註冊處查詢' }}</button><p v-if="lookupError" class="error">{{ lookupError }}</p><div v-if="lookupResult" class="lookup-result"><strong>{{ lookupResult.name }}</strong><span>BRN：{{ lookupResult.registrationNo }}</span><span>英文名稱：{{ lookupResult.englishName || '—' }}</span><span>成立日期：{{ lookupResult.incorporatedOn || '—' }}</span><span>公司類型：{{ lookupResult.companyType || '—' }}</span><span>註冊地址：{{ lookupResult.address || '—' }}</span><button class="button primary" @click="applyLookup">套用查詢結果</button></div></div><button class="button primary full" @click="saveCompanyDialog">儲存公司</button></template></div></div>
</template>
<script setup>
import { ref, computed, watch, onMounted } from 'vue'
import { api } from '../api'
import ExpiryPanel from '../components/ExpiryPanel.vue'
const props = defineProps({ customers: Array, initialCustomer: String })
const emit = defineEmits(['error','saved','plate'])
const statuses = ['存續','經營異常','註銷中','已註銷']
const customerId = ref(props.initialCustomer || ''), groups = ref([]), companies = ref([]), dialog = ref(null), dialogForm = ref({}), editingCompany = ref(''), form = ref({}), newGroup = ref({name:'',notes:''}), lookingUp = ref(false), lookupResult = ref(null), lookupError = ref('')
const ungrouped = computed(() => companies.value.filter(item => !item.group_id))
const foreignCompanies = group => group.companies.filter(item => item.jurisdiction !== '內地')
const mainlandCompanies = group => group.companies.filter(item => item.jurisdiction === '內地')
const statusClass = status => ({'經營異常':'warning','註銷中':'warning','已註銷':'dissolved'}[status] || '')
const companyCardClass = company => company.status === '已註銷' ? 'company-dissolved' : ''
function resetForm() { editingCompany.value = ''; form.value = { groupId:'', jurisdiction:'香港', name:'', registrationNo:'', incorporatedOn:'', taxpayerType:'', status:'存續', statusChangedOn:'', notes:'' } }
async function load() { if (!customerId.value) { groups.value = []; companies.value = []; return } try { [groups.value,companies.value] = await Promise.all([api(`/company-groups?customerId=${encodeURIComponent(customerId.value)}`),api(`/companies?customerId=${encodeURIComponent(customerId.value)}`)]) } catch (error) { emit('error',error) } }
async function createGroup() { try { await api('/company-groups','POST',{customerId:customerId.value,...newGroup.value}); newGroup.value={name:'',notes:''}; await load(); emit('saved','公司組已新增') } catch (error) { emit('error',error) } }
function editGroup(group) { dialog.value='group'; dialogForm.value={name:group.name,notes:group.notes||'',id:group.id} }
async function saveGroup() { try { await api(`/company-groups/${dialogForm.value.id}`,'PATCH',{name:dialogForm.value.name,notes:dialogForm.value.notes}); dialog.value=null; await load(); emit('saved','公司組已更新') } catch (error) { emit('error',error) } }
function editCompany(company) { dialog.value='company'; lookupResult.value=null; lookupError.value=''; dialogForm.value={...company,groupId:company.group_id||'',registrationNo:company.registration_no||'',incorporatedOn:company.incorporated_on||'',taxpayerType:company.taxpayer_type||'',status:company.status||'存續',statusChangedOn:company.status_changed_on||'',notes:company.notes||''} }
async function lookupCompany() { lookupResult.value=null; lookupError.value=''; if (!/^\d{8}$/.test(String(dialogForm.value.registrationNo || ''))) { lookupError.value='請先填寫 8 位商業登記號碼'; return } lookingUp.value=true; try { lookupResult.value=await api(`/companies/${dialogForm.value.id}/hk-lookup`,'POST') } catch (error) { lookupError.value=error.message } finally { lookingUp.value=false } }
function applyLookup() { if (!lookupResult.value) return; dialogForm.value.name=lookupResult.value.name || dialogForm.value.name; dialogForm.value.incorporatedOn=lookupResult.value.incorporatedOn || dialogForm.value.incorporatedOn }
async function saveCompanyDialog() { try { await api(`/companies/${dialogForm.value.id}`,'PATCH',{...dialogForm.value,customerId:customerId.value}); dialog.value=null; await load(); emit('saved','公司已更新') } catch (error) { emit('error',error) } }
async function saveCompany() { try { await api(editingCompany.value ? `/companies/${editingCompany.value}` : '/companies',editingCompany.value ? 'PATCH' : 'POST',{...form.value,customerId:customerId.value}); resetForm(); await load(); emit('saved','公司已儲存') } catch (error) { emit('error',error) } }
watch(customerId, () => { resetForm(); load() }); watch(() => props.initialCustomer, value => { if (value) customerId.value=value }); onMounted(() => { resetForm(); load() })
</script>
